        }
    }
}
```

Or run it locally over stdio:

```json
{
    "mcpServers": {
        "flagsmith": {
            "command": "uvx",
            "args": ["--from", "git+https://github.com/Flagsmith/flagsmith.git@main#subdirectory=mcp", "flagsmith-mcp"],
            "env": { "TRANSPORT": "stdio", "FLAGSMITH_API_TOKEN": "<your-api-key>" }
        }
    }
}
```

